package app.noir.mobile;
import android.content.Intent;
import android.graphics.Typeface;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import org.json.*;
import java.util.*;

/** Local prompt policy; the response itself uses the existing synced review and reaction fields. */
final class PhoneJustWatched {
 static final String MODE="afterWatchingPrompt",IGNORES="afterWatchingIgnores",QUIET="afterWatchingQuiet";
 static final String[] MODES={"Always","Finales and movies only","Never"};
 final MainActivity a;PopupWindow popup;Runnable timeout;boolean engaged;long sessionStart;String profile="";
 PhoneJustWatched(MainActivity activity){a=activity;}
 android.app.Application.ActivityLifecycleCallbacks playbackLifecycle;
 void attach(){if(playbackLifecycle!=null)return;playbackLifecycle=new android.app.Application.ActivityLifecycleCallbacks(){public void onActivityCreated(android.app.Activity activity,android.os.Bundle state){if(activity instanceof PlayerActivity&&sessionStart==0&&NoirApp.data==a.data)leavingForPlayer();}public void onActivityStarted(android.app.Activity activity){}public void onActivityResumed(android.app.Activity activity){}public void onActivityPaused(android.app.Activity activity){}public void onActivityStopped(android.app.Activity activity){}public void onActivitySaveInstanceState(android.app.Activity activity,android.os.Bundle state){}public void onActivityDestroyed(android.app.Activity activity){}};a.getApplication().registerActivityLifecycleCallbacks(playbackLifecycle);}
 void detach(){close(false);if(playbackLifecycle!=null)a.getApplication().unregisterActivityLifecycleCallbacks(playbackLifecycle);playbackLifecycle=null;}

 static void accessible(View view){if(view.isClickable()){view.setFocusable(true);if(view.getContentDescription()==null&&view instanceof TextView)view.setContentDescription(((TextView)view).getText());}if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++)accessible(((ViewGroup)view).getChildAt(n));}
 static boolean allowed(DataStore data,boolean finale){String mode=data.prefs().optString(MODE,"Always");return !mode.equals("Never")&&!data.prefs().optBoolean(QUIET)&&(mode.equals("Always")||finale);}
 static void answered(DataStore data){data.pref(IGNORES,0);}
 static boolean ignored(DataStore data){int n=data.prefs().optInt(IGNORES)+1;data.pref(IGNORES,n);if(n>=5&&!data.prefs().optBoolean(QUIET)){data.pref(QUIET,true);return true;}return false;}
 static void keepAsking(DataStore data){data.pref(QUIET,false);data.pref(IGNORES,0);data.pref(MODE,"Always");}
 static JSONObject finished(List<JSONObject> items,long since,long now){
  JSONObject latest=null;long at=since-1;for(JSONObject i:items){JSONObject p=i.optJSONObject("progress");if(p==null)continue;long t=DataStore.date(p.optString("updatedAt"));if(t>=since&&(t>at||t==at&&latest!=null&&(!p.optBoolean("completed")||PhoneSmart.before(latest,i)))){at=t;latest=i;}}
  if(latest==null||now-at>5*60000L)return null;JSONObject p=latest.optJSONObject("progress");return p.optBoolean("completed")?latest:null;
 }
 // A finale needs proof the season is over: a later season exists. Missing episodes alone prove nothing.
 static boolean finale(JSONObject item,List<JSONObject> items){if(item.optBoolean("movie"))return true;boolean later=false;for(JSONObject i:items)if(i.optString("group").equals(item.optString("group"))){if(i.optInt("season")==item.optInt("season")&&i.optInt("episode")>item.optInt("episode"))return false;if(i.optInt("season")>item.optInt("season"))later=true;}return later;}
 void leavingForPlayer(){sessionStart=System.currentTimeMillis();profile=a.data.profileId;close(false);}
 void returned(){if(sessionStart==0)return;long since=sessionStart;sessionStart=0;if(!a.data.profileId.equals(profile))return;List<JSONObject> items=DataStore.objects(a.data.items());JSONObject item=finished(items,since,System.currentTimeMillis());if(item==null)return;JSONObject p=item.optJSONObject("progress");String token=item.optString("id")+":"+p.optString("viewingId")+":"+p.optString("updatedAt");if(token.equals(a.data.prefs().optString("afterWatchingSeen")))return;a.data.pref("afterWatchingSeen",token);boolean last=finale(item,items);JSONObject schedules=a.browsingSettings().optJSONObject("schedules");if(schedules!=null&&!item.optBoolean("movie")){boolean sameSeason=false,laterSeason=false;for(JSONObject e:DataStore.objects(schedules.optJSONArray(item.optString("group")))){if(e.optInt("season")==item.optInt("season")&&e.optInt("episode")>item.optInt("episode"))sameSeason=true;if(e.optInt("season")>item.optInt("season"))laterSeason=true;}if(sameSeason)last=false;else if(laterSeason)last=true;}if(allowed(a.data,last))show(item);}
 void interact(){engaged=true;answered(a.data);if(timeout!=null){a.handler.removeCallbacks(timeout);a.handler.postDelayed(timeout,12000);}}
 void close(boolean count){if(timeout!=null)a.handler.removeCallbacks(timeout);PopupWindow old=popup;popup=null;if(old!=null){old.setOnDismissListener(null);old.dismiss();if(count&&!engaged&&ignored(a.data))quietNotice();}}
 void quietNotice(){a.undoable(Loc.t("Watching prompts are quiet now. Find reactions in History."),()->{keepAsking(a.data);a.toast(Loc.t("Keep asking"));});if(a.undoView instanceof ViewGroup){ViewGroup bar=(ViewGroup)a.undoView;for(int n=0;n<bar.getChildCount();n++)if(bar.getChildAt(n) instanceof TextView&&((TextView)bar.getChildAt(n)).getText().toString().equals(Loc.t("Undo")))((TextView)bar.getChildAt(n)).setText(Loc.t("Keep asking"));}}
 void show(JSONObject item){
  close(false);engaged=false;LinearLayout card=a.column();card.setLayoutDirection(Loc.arabic?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);card.setPadding(a.dp(14),a.dp(10),a.dp(14),a.dp(10));card.setBackground(MainActivity.bg(0xff161618,a.dp(16)));card.setElevation(a.dp(12));card.setTag("just-watched");
  LinearLayout header=new LinearLayout(a);TextView title=a.text(Loc.t("Just watched")+" · "+item.optString("title")+(item.optBoolean("movie")?"":" · "+MainActivity.episode(item)),14,MainActivity.GOLD);title.setTypeface(null,Typeface.BOLD);title.setMaxLines(2);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView x=a.ui.small("✕",()->close(true),false);x.setContentDescription(Loc.t("Close"));x.setFocusable(true);header.addView(x);card.addView(header);
  final float[] down={0};header.setOnTouchListener((v,e)->{if(e.getActionMasked()==MotionEvent.ACTION_DOWN)down[0]=e.getRawX();if(e.getActionMasked()==MotionEvent.ACTION_UP&&Math.abs(e.getRawX()-down[0])>a.dp(65)){close(true);return true;}return true;});
  ScrollView scroll=new ScrollView(a);scroll.addView(controls(item,this::interact));card.addView(scroll,new LinearLayout.LayoutParams(-1,a.dp(240)));
  popup=new PopupWindow(card,Math.min(a.getResources().getDisplayMetrics().widthPixels-a.dp(24),a.dp(420)),-2,true);popup.setBackgroundDrawable(MainActivity.bg(0xff161618,a.dp(16)));popup.setOutsideTouchable(true);popup.setInputMethodMode(PopupWindow.INPUT_METHOD_NEEDED);popup.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE);popup.setOnDismissListener(()->{popup=null;if(timeout!=null)a.handler.removeCallbacks(timeout);if(!engaged&&ignored(a.data))quietNotice();});card.setFocusableInTouchMode(true);card.setOnKeyListener((v,k,e)->{if(k==KeyEvent.KEYCODE_ESCAPE&&e.getAction()==KeyEvent.ACTION_UP){close(true);return true;}return false;});
  try{popup.showAtLocation(a.getWindow().getDecorView(),Gravity.BOTTOM|Gravity.CENTER_HORIZONTAL,0,a.dp(78));Motion.riseIn(card,0);timeout=()->close(true);a.handler.postDelayed(timeout,12000);}catch(WindowManager.BadTokenException ignored){close(false);}
 }
 View controls(JSONObject item,Runnable interacted){
  LinearLayout box=a.column();box.setTag("just-watched-controls");String id=item.optString("id");LinearLayout moods=new LinearLayout(a);String[] keys={"loved","funny","wow","sad","meh"},icons={"♥","☺","✦","☂","–"};for(int n=0;n<keys.length;n++){String mood=keys[n];TextView chip=a.ui.chip(icons[n],()->{interacted.run();a.data.reaction(id,mood);Motion.haptic(box);for(int k=0;k<moods.getChildCount();k++)moods.getChildAt(k).setAlpha(mood.equals(moods.getChildAt(k).getTag())?1:.5f);},false);chip.setMinHeight(a.dp(48));chip.setMinWidth(a.dp(48));chip.setTag(mood);chip.setAlpha(a.data.reaction(id).isEmpty()||a.data.reaction(id).equals(mood)?1:.5f);chip.setContentDescription(Loc.t(mood));chip.setFocusable(true);moods.addView(chip);}box.addView(a.ui.row(moods));
  RatingBar stars=new RatingBar(a,null,android.R.attr.ratingBarStyleSmall);stars.setIsIndicator(false);stars.setNumStars(5);stars.setStepSize(.5f);stars.setRating(DataStore.rating10(item)/2f);stars.setProgressTintList(android.content.res.ColorStateList.valueOf(MainActivity.GOLD));stars.setContentDescription(Loc.t("Rating · optional"));stars.setFocusable(true);box.addView(stars,new LinearLayout.LayoutParams(-2,a.dp(44)));stars.setOnRatingBarChangeListener((bar,rating,user)->{if(user){interacted.run();JSONObject fresh=a.data.item(id),review=fresh==null?null:fresh.optJSONObject("review");a.data.review10(id,Math.round(rating*2),review==null?"":review.optString("note"));}});
  LinearLayout noteBox=a.column();noteBox.setVisibility(View.GONE);EditText note=new EditText(a);note.setTextColor(MainActivity.WHITE);note.setHintTextColor(MainActivity.MUTED);note.setHint(Loc.t("Add a note…"));note.setContentDescription(Loc.t("Add a note…"));JSONObject review=item.optJSONObject("review");note.setText(review==null?"":review.optString("note"));note.setOnFocusChangeListener((v,focused)->{if(focused&&timeout!=null)a.handler.removeCallbacks(timeout);});note.setMaxLines(3);note.setSingleLine(true);note.setImeOptions(EditorInfo.IME_ACTION_DONE);note.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(10000)});noteBox.addView(note);Runnable save=()->{interacted.run();JSONObject fresh=a.data.item(id);a.data.review10(id,DataStore.rating10(fresh),note.getText().toString());note.clearFocus();noteBox.setVisibility(View.GONE);android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)a.getSystemService(android.content.Context.INPUT_METHOD_SERVICE);if(keyboard!=null)keyboard.hideSoftInputFromWindow(note.getWindowToken(),0);};note.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_DONE||event!=null&&event.getKeyCode()==KeyEvent.KEYCODE_ENTER&&event.getAction()==KeyEvent.ACTION_UP){save.run();return true;}return false;});noteBox.addView(a.ui.chip("Done",save,false));box.addView(a.ui.chip("Add a note…",()->{interacted.run();noteBox.setVisibility(View.VISIBLE);note.requestFocus();},false));box.addView(noteBox);
  TextView community=a.ui.chip("💬 What others said",()->{interacted.run();a.startActivity(new Intent(a,ReviewsActivity.class).putExtra("id",id));},false);community.setContentDescription(Loc.t("💬 What others said"));community.setFocusable(true);box.addView(community);accessible(box);return box;
 }
 static void settings(HistoryToolsActivity activity){DataStore data=activity.data;activity.heading("After watching, ask how it was");String current=data.prefs().optBoolean(QUIET)?"Never":data.prefs().optString(MODE,"Always");activity.button(current,()->{String[] labels=Arrays.stream(MODES).map(Loc::t).toArray(String[]::new);new android.app.AlertDialog.Builder(activity).setTitle(Loc.t("After watching, ask how it was")).setSingleChoiceItems(labels,Arrays.asList(MODES).indexOf(current),(d,n)->{data.pref(MODE,MODES[n]);data.pref(QUIET,false);data.pref(IGNORES,0);d.dismiss();activity.render();}).setNegativeButton(Loc.t("Cancel"),null).show();},false);}
}
